-- ============================================================================== -- Code Spark - Production PostgreSQL DDL Schema -- Comprehensive Relational Database Design with Constraints & B-Tree Indexes -- ============================================================================== -- 1. Users Table CREATE TABLE IF NOT EXISTS users ( id VARCHAR(64) PRIMARY KEY, username VARCHAR(64) UNIQUE NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, hashed_password VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('student', 'assistant', 'admin')), is_active BOOLEAN DEFAULT TRUE, is_verified BOOLEAN DEFAULT TRUE, phone VARCHAR(32), avatar_url TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 2. Assistant Permissions Table CREATE TABLE IF NOT EXISTS assistant_permissions ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, permission VARCHAR(64) NOT NULL, granted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT uq_assistant_permission UNIQUE (user_id, permission) ); -- 3. Subscription Codes Table CREATE TABLE IF NOT EXISTS subscription_codes ( id VARCHAR(64) PRIMARY KEY, code VARCHAR(64) UNIQUE NOT NULL, code_hash VARCHAR(128) NOT NULL, duration_type VARCHAR(32) NOT NULL CHECK (duration_type IN ('1_MONTH', '3_MONTHS', '6_MONTHS', '12_MONTHS', 'LIFETIME', 'CUSTOM')), duration_days INTEGER NOT NULL, status VARCHAR(32) NOT NULL CHECK (status IN ('ACTIVE', 'USED', 'EXPIRED', 'DISABLED')), created_by VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, used_by VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, disabled BOOLEAN DEFAULT FALSE, metadata_json TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, activated_at TIMESTAMP WITH TIME ZONE, expires_at TIMESTAMP WITH TIME ZONE ); -- 4. Subscriptions Table CREATE TABLE IF NOT EXISTS subscriptions ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, code_id VARCHAR(64) REFERENCES subscription_codes(id) ON DELETE SET NULL, status VARCHAR(32) NOT NULL CHECK (status IN ('ACTIVE', 'EXPIRED', 'DISABLED')), started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, expires_at TIMESTAMP WITH TIME ZONE, is_lifetime BOOLEAN DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 5. Courses Table CREATE TABLE IF NOT EXISTS courses ( id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) UNIQUE NOT NULL, description TEXT, thumbnail_url TEXT, order_index INTEGER DEFAULT 0, is_published BOOLEAN DEFAULT TRUE, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 6. Units Table CREATE TABLE IF NOT EXISTS units ( id VARCHAR(64) PRIMARY KEY, course_id VARCHAR(64) NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title VARCHAR(255) NOT NULL, description TEXT, order_index INTEGER DEFAULT 0, is_published BOOLEAN DEFAULT TRUE, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 7. Lessons Table CREATE TABLE IF NOT EXISTS lessons ( id VARCHAR(64) PRIMARY KEY, unit_id VARCHAR(64) NOT NULL REFERENCES units(id) ON DELETE CASCADE, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL, description TEXT, content_markdown TEXT, video_type VARCHAR(32) NOT NULL CHECK (video_type IN ('youtube', 'uploaded', 'none')), video_url TEXT, video_id VARCHAR(128), duration_seconds REAL DEFAULT 0, order_index INTEGER DEFAULT 0, is_published BOOLEAN DEFAULT TRUE, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 8. Lesson Progress Table CREATE TABLE IF NOT EXISTS lesson_progress ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id VARCHAR(64) NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, last_video_position_seconds REAL DEFAULT 0, watch_percentage REAL DEFAULT 0, is_completed BOOLEAN DEFAULT FALSE, completed_at TIMESTAMP WITH TIME ZONE, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT uq_user_lesson_progress UNIQUE (user_id, lesson_id) ); -- 9. Educational Resources Table CREATE TABLE IF NOT EXISTS educational_resources ( id VARCHAR(64) PRIMARY KEY, unit_id VARCHAR(64) REFERENCES units(id) ON DELETE SET NULL, lesson_id VARCHAR(64) REFERENCES lessons(id) ON DELETE SET NULL, title VARCHAR(255) NOT NULL, description TEXT, resource_type VARCHAR(32) NOT NULL CHECK (resource_type IN ('drive_link', 'uploaded_file')), file_url TEXT NOT NULL, file_size_bytes BIGINT DEFAULT 0, file_format VARCHAR(32), access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), is_published BOOLEAN DEFAULT TRUE, created_by VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 10. Exercises Table CREATE TABLE IF NOT EXISTS exercises ( id VARCHAR(64) PRIMARY KEY, unit_id VARCHAR(64) REFERENCES units(id) ON DELETE SET NULL, lesson_id VARCHAR(64) REFERENCES lessons(id) ON DELETE SET NULL, title VARCHAR(255) NOT NULL, description TEXT, instructions TEXT, starter_code TEXT, expected_output TEXT, test_cases_json TEXT, language VARCHAR(32) NOT NULL CHECK (language IN ('python', 'javascript', 'html', 'css')), difficulty VARCHAR(32) NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard')), solution_code TEXT, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), is_published BOOLEAN DEFAULT TRUE, order_index INTEGER DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 11. Exercise Submissions Table CREATE TABLE IF NOT EXISTS exercise_submissions ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, exercise_id VARCHAR(64) NOT NULL REFERENCES exercises(id) ON DELETE CASCADE, submitted_code TEXT NOT NULL, status VARCHAR(32) NOT NULL CHECK (status IN ('PASSED', 'FAILED', 'ERROR')), output TEXT, tests_passed INTEGER DEFAULT 0, tests_total INTEGER DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 12. Question Bank Table CREATE TABLE IF NOT EXISTS question_bank ( id VARCHAR(64) PRIMARY KEY, question_text TEXT NOT NULL, question_type VARCHAR(32) NOT NULL CHECK (question_type IN ('multiple_choice', 'true_false', 'code', 'essay')), options_json TEXT, correct_answer TEXT NOT NULL, explanation TEXT, difficulty VARCHAR(32) NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard')), topic VARCHAR(128), unit_id VARCHAR(64) REFERENCES units(id) ON DELETE SET NULL, lesson_id VARCHAR(64) REFERENCES lessons(id) ON DELETE SET NULL, tags_json TEXT, status VARCHAR(32) DEFAULT 'active', created_by VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 13. Quizzes Table CREATE TABLE IF NOT EXISTS quizzes ( id VARCHAR(64) PRIMARY KEY, lesson_id VARCHAR(64) REFERENCES lessons(id) ON DELETE SET NULL, unit_id VARCHAR(64) REFERENCES units(id) ON DELETE SET NULL, title VARCHAR(255) NOT NULL, description TEXT, passing_score REAL DEFAULT 70.0, time_limit_minutes INTEGER DEFAULT 15, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), is_published BOOLEAN DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 14. Quiz Questions Table CREATE TABLE IF NOT EXISTS quiz_questions ( id VARCHAR(64) PRIMARY KEY, quiz_id VARCHAR(64) NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, question_id VARCHAR(64) NOT NULL REFERENCES question_bank(id) ON DELETE CASCADE, points REAL DEFAULT 1.0, order_index INTEGER DEFAULT 0, CONSTRAINT uq_quiz_question UNIQUE (quiz_id, question_id) ); -- 15. Quiz Attempts Table CREATE TABLE IF NOT EXISTS quiz_attempts ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, quiz_id VARCHAR(64) NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, answers_json TEXT, score REAL DEFAULT 0, total_possible REAL DEFAULT 0, percentage REAL DEFAULT 0, is_passed BOOLEAN DEFAULT FALSE, started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, completed_at TIMESTAMP WITH TIME ZONE ); -- 16. Exams Table CREATE TABLE IF NOT EXISTS exams ( id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, description TEXT, duration_minutes INTEGER NOT NULL DEFAULT 45, passing_score REAL DEFAULT 75.0, max_attempts INTEGER DEFAULT 1, is_randomized BOOLEAN DEFAULT FALSE, start_window TIMESTAMP WITH TIME ZONE, end_window TIMESTAMP WITH TIME ZONE, access_type VARCHAR(32) NOT NULL CHECK (access_type IN ('PUBLIC', 'SUBSCRIBERS_ONLY')), is_published BOOLEAN DEFAULT TRUE, created_by VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ); -- 17. Exam Questions Table CREATE TABLE IF NOT EXISTS exam_questions ( id VARCHAR(64) PRIMARY KEY, exam_id VARCHAR(64) NOT NULL REFERENCES exams(id) ON DELETE CASCADE, question_id VARCHAR(64) NOT NULL REFERENCES question_bank(id) ON DELETE CASCADE, points REAL DEFAULT 1.0, order_index INTEGER DEFAULT 0, CONSTRAINT uq_exam_question UNIQUE (exam_id, question_id) ); -- 18. Exam Attempts Table CREATE TABLE IF NOT EXISTS exam_attempts ( id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, exam_id VARCHAR(64) NOT NULL REFERENCES exams(id) ON DELETE CASCADE, attempt_number INTEGER DEFAULT 1, answers_json TEXT, score REAL DEFAULT 0, total_possible REAL DEFAULT 0, percentage REAL DEFAULT 0, is_passed BOOLEAN DEFAULT FALSE, status VARCHAR(32) NOT NULL CHECK (status IN ('IN_PROGRESS', 'Sound: linear-gradient(135deg, rgba(14, 165, 233, 0.12), rgba(0, 229, 255, 0.04)); box-shadow: 0 0 0 2px var(--color-cyan-accent), 0 8px 24px rgba(0, 229, 255, 0.2); } .plan-card-badge { position: absolute; top: -10px; left: 12px; background: var(--color-primary); color: #FFF; font-size: 0.7rem; font-weight: 800; padding: 2px 8px; border-radius: 9999px; box-shadow: 0 2px 6px rgba(0,0,0,0.3); } .plan-price-tag { font-family: var(--font-mono); font-size: 1.5rem; font-weight: 900; color: #10B981; margin: 0.5rem 0; } .screenshot-preview-container { border: 2px dashed var(--color-border); border-radius: var(--radius-md); padding: 1rem; text-align: center; background: var(--color-bg-surface); transition: border-color 0.2s; position: relative; } .screenshot-preview-container.drag-over { border-color: var(--color-primary); background: rgba(14, 165, 233, 0.08); } /* ========================================================================== Professional IDE Stacked Layout (Code Editor Top, Terminal Bottom) ========================================================================== */ .playground-ide-layout { display: flex \!important; flex-direction: column \!important; height: calc(100vh - 170px) \!important; min-height: 650px \!important; position: relative \!important; border-radius: var(--radius-md) \!important; border: 1px solid var(--color-border) \!important; background: #030712 \!important; overflow: hidden \!important; box-shadow: 0 10px 30px rgba(0,0,0,0.6) \!important; } .playground-editor-section { display: flex; flex-direction: column; overflow: hidden; min-height: 120px; background: #050B17; position: relative; } .playground-drag-divider { height: 12px \!important; background: #0B132B \!important; border-top: 1px solid #1E293B \!important; border-bottom: 1px solid #1E293B \!important; cursor: row-resize \!important; user-select: none \!important; display: flex \!important; align-items: center \!important; justify-content: center \!important; z-index: 20 \!important; transition: background 0.15s ease, box-shadow 0.15s ease; touch-action: none; } .playground-drag-divider:hover, .playground-drag-divider.dragging { background: #0EA5E9 \!important; box-shadow: 0 0 12px rgba(14, 165, 233, 0.6) \!important; } .playground-drag-divider .handle-bar { width: 48px; height: 4px; border-radius: 2px; background: #64748B; transition: background 0.15s; } .playground-drag-divider:hover .handle-bar, .playground-drag-divider.dragging .handle-bar { background: #FFFFFF; } .playground-terminal-section { display: flex; flex-direction: column; overflow: hidden; min-height: 120px; flex: 1; background: #02050D; position: relative; } .playground-ide-layout.maximized .playground-editor-section, .playground-ide-layout.maximized .playground-drag-divider { display: none \!important; } .playground-ide-layout.maximized .playground-terminal-section { height: 100% \!important; flex: 1 1 100% \!important; } .terminal-console-output { flex: 1 \!important; height: 100% \!important; width: 100% \!important; margin: 0 \!important; padding: 1rem 1.25rem \!important; font-family: var(--font-mono) \!important; font-size: 0.95rem \!important; line-height: 1.65 \!important; direction: ltr \!important; text-align: left \!important; background: #02050D \!important; color: #E0F2FE \!important; overflow-y: auto \!important; overflow-x: auto \!important; white-space: pre-wrap \!important; word-break: break-word \!important; border-top: 1px solid #1E293B \!important; } @media (max-width: 768px) { .playground-ide-layout { height: auto \!important; min-height: 800px \!important; } } /* ========================================================================== Professional IDE Stacked Layout (Code Editor Top, Terminal Bottom) ========================================================================== */ .playground-ide-layout { display: flex \!important; flex-direction: column \!important; height: calc(100vh - 170px) \!important; min-height: 650px \!important; position: relative \!important; border-radius: var(--radius-md) \!important; border: 1px solid var(--color-border) \!important; background: #030712 \!important; overflow: hidden \!important; box-shadow: 0 10px 30px rgba(0,0,0,0.6) \!important; } .playground-editor-section { display: flex \!important; flex-direction: column \!important; overflow: hidden \!important; min-height: 120px \!important; background: #050B17 \!important; position: relative \!important; } .playground-drag-divider { height: 12px \!important; background: #0B132B \!important; border-top: 1px solid #1E293B \!important; border-bottom: 1px solid #1E293B \!important; cursor: row-resize \!important; user-select: none \!important; display: flex \!important; align-items: center \!important; justify-content: center \!important; z-index: 20 \!important; transition: background 0.15s ease, box-shadow 0.15s ease \!important; touch-action: none \!important; } .playground-drag-divider:hover, .playground-drag-divider.dragging { background: #0EA5E9 \!important; box-shadow: 0 0 12px rgba(14, 165, 233, 0.6) \!important; } .playground-drag-divider .handle-bar { width: 48px \!important; height: 4px \!important; border-radius: 2px \!important; background: #64748B \!important; transition: background 0.15s \!important; } .playground-drag-divider:hover .handle-bar, .playground-drag-divider.dragging .handle-bar { background: #FFFFFF \!important; } .playground-terminal-section { display: flex \!important; flex-direction: column \!important; overflow: hidden \!important; min-height: 120px \!important; flex: 1 \!important; background: #02050D \!important; position: relative \!important; } .playground-ide-layout.maximized .playground-editor-section, .playground-ide-layout.maximized .playground-drag-divider { display: none \!important; } .playground-ide-layout.maximized .playground-terminal-section { height: 100% \!important; flex: 1 1 100% \!important; } .terminal-console-output { flex: 1 \!important; height: 100% \!important; width: 100% \!important; margin: 0 \!important; padding: 1rem 1.25rem \!important; font-family: var(--font-mono) \!important; font-size: 0.95rem \!important; line-height: 1.65 \!important; direction: ltr \!important; text-align: left \!important; background: #02050D \!important; color: #E0F2FE \!important; overflow-y: auto \!important; overflow-x: auto \!important; white-space: pre-wrap \!important; word-break: break-word \!important; border-top: 1px solid #1E293B \!important; } @media (max-width: 768px) { .playground-ide-layout { height: auto \!important; min-height: 800px \!important; } }